// <autogenerated />
using System;
using System.Reflection;
using System.Net.Sockets;
using System.Collections.Concurrent;

[assembly: global::System.Runtime.Versioning.TargetFrameworkAttribute(".NETCoreApp,Version=v9.0", FrameworkDisplayName = ".NET 9.0")]

namespace MemoryManagementFix
{
    public class ResourceManagingClass : IDisposable
    {
        private bool _disposed;
        private TcpClient _tcpClient;
        private ConcurrentDictionary<int, byte[]> _largeByteArrays;

        public ResourceManagingClass()
        {
            _tcpClient = new TcpClient();
            _largeByteArrays = new ConcurrentDictionary<int, byte[]>();
        }

        public void AddLargeByteArray(int key, byte[] data)
        {
            if (_disposed) throw new ObjectDisposedException(nameof(ResourceManagingClass));

            _largeByteArrays[key] = data;
        }

        public void PerformOperation()
        {
            if (_disposed) throw new ObjectDisposedException(nameof(ResourceManagingClass));

            // Simulation of some operations involving strings and sockets
            var data = _largeByteArrays.GetOrAdd(1, _ => new byte[1024]);
            var connection = _tcpClient.Client.RemoteEndPoint as System.Net.IPEndPoint;

            if (connection == null)
            {
                connection = new System.Net.IPEndPoint(System.Net.IPAddress.Loopback, 0);
            }

            string operationDetails = connection.ToString();
        }

        public void CleanupResources()
        {
            _largeByteArrays.Clear();
        }

        protected virtual void Dispose(bool disposing)
        {
            if (!_disposed)
            {
                if (disposing)
                {
                    _tcpClient?.Dispose();
                }

                _tcpClient = null;
                _largeByteArrays.Clear();
                _disposed = true;
            }
        }

        public void Dispose()
        {
            Dispose(true);
            GC.SuppressFinalize(this);
        }
    }

    public class Logger : IDisposable
    {
        private bool _disposed;
        private LoggerFactory _loggerFactory;

        public Logger(LoggerFactory loggerFactory)
        {
            _loggerFactory = loggerFactory ?? throw new ArgumentNullException(nameof(loggerFactory));
        }

        public void Log(string message)
        {
            if (_disposed) throw new ObjectDisposedException(nameof(Logger));

            using (var scope = _loggerFactory.CreateScope("LogScope"))
            {
                var logger = _loggerFactory.CreateLogger("Logger");
                logger.LogInformation(message);
            }
        }

        protected virtual void Dispose(bool disposing)
        {
            if (!_disposed)
            {
                if (disposing)
                {
                    _loggerFactory?.Dispose();
                }

                _loggerFactory = null;
                _disposed = true;
            }
        }

        public void Dispose()
        {
            Dispose(true);
            GC.SuppressFinalize(this);
        }
    }
}
